// Build-time generator: analyse + recompile every synthetic test program into one C++ file.
#include <cstdio>
#include <fstream>
#include <string>

#include "analysis/code_analysis.h"
#include "recomp/emitter.h"
#include "recomp_programs.h"

int main(int argc, char** argv) {
  if (argc != 2) {
    std::fputs("usage: recomp_selftest_gen OUT.cpp\n", stderr);
    return 2;
  }
  using namespace lantern;
  const auto programs = test::test_programs();
  std::string out =
      "// Generated by recomp_selftest_gen from synthetic programs (tests/recomp_programs.h).\n"
      "#include \"ee/semantics.h\"\n#include \"recomp/runtime.h\"\n";
  std::string registry =
      "namespace selftest {\nusing RegisterFn = void (*)(lantern::recomp::Runtime&);\n"
      "extern const RegisterFn kRegister[] = {\n";
  for (size_t i = 0; i < programs.size(); ++i) {
    const auto& p = programs[i];
    analysis::CodeImage img{p.base, p.code};
    auto ca = analysis::analyze_code(img, {{p.entry}, true, false});
    recomp::EmitOptions opt;
    opt.ns = "selftest_p" + std::to_string(i);
    opt.register_fn = "register_program";
    auto mod = recomp::emit_module(img, ca, opt);
    if (mod.stats.unimplemented) {
      std::fprintf(stderr, "program %s: %llu unimplemented sites\n", p.name.c_str(),
                   static_cast<unsigned long long>(mod.stats.unimplemented));
      for (auto& [k, v] : mod.stats.missing_ops)
        std::fprintf(stderr, "  %s x%llu\n", k.c_str(), static_cast<unsigned long long>(v));
      return 1;
    }
    auto strip = [](std::string s) {
      for (const char* line : {"#pragma once\n", "#include \"recomp/runtime.h\"\n", "#include \"module.h\"\n",
                               "#include \"ee/semantics.h\"\n"}) {
        for (size_t pos; (pos = s.find(line)) != std::string::npos;) s.erase(pos, std::string(line).size());
      }
      return s;
    };
    out += strip(mod.header);
    for (const auto& src : mod.sources) out += strip(src);
    registry += "    &" + opt.ns + "::register_program,\n";
  }
  registry += "};\nextern const size_t kProgramCount = " + std::to_string(programs.size()) + ";\n}\n";
  std::ofstream(argv[1]) << out << registry;
  return 0;
}
